const http = require('http');
const crypto = require('crypto');

const SECRET_KEY = crypto.randomBytes(32);
const sessions = Object.create(null);
const users = Object.create(null);

function createUser(username, password, role) {
  const salt = crypto.randomBytes(16).toString('hex');
  const passwordHash = crypto.scryptSync(password, salt, 64).toString('hex');
  users[username] = { passwordHash, salt, role };
}

// Initialize users with per-user random salts
createUser('admin', 'admin123', 'admin');
createUser('user1', 'userpass', 'viewer');

function generateToken(username, role, expiresIn) {
  const header = Buffer.from(JSON.stringify({alg: 'HS256', typ: 'JWT'})).toString('base64url');
  const now = Math.floor(Date.now() / 1000);
  const payload = Buffer.from(JSON.stringify({
    sub: username,
    role: role,
    iat: now,
    exp: now + expiresIn
  })).toString('base64url');
  const signature = crypto.createHmac('sha256', SECRET_KEY)
    .update(header + '.' + payload)
    .digest('base64url');
  return header + '.' + payload + '.' + signature;
}

function verifyToken(token) {
  if (typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 3) return null;

  const [header, payload, signature] = parts;

  // Verify header
  try {
    const headerObj = JSON.parse(Buffer.from(header, 'base64url').toString());
    if (headerObj.alg !== 'HS256') return null;
  } catch(e) { return null; }

  // Verify signature
  const expectedSig = crypto.createHmac('sha256', SECRET_KEY)
    .update(header + '.' + payload)
    .digest('base64url');

  if (!timingSafeCompare(signature, expectedSig)) return null;

  // Decode payload
  try {
    const payloadObj = JSON.parse(Buffer.from(payload, 'base64url').toString());
    if (payloadObj.exp < Math.floor(Date.now() / 1000)) return null;
    return payloadObj;
  } catch(e) { return null; }
}

function timingSafeCompare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const bufA = Buffer.from(a);
  const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

// Access control matrix
const PERMISSIONS = Object.create(null);
PERMISSIONS['admin'] = ['read', 'write', 'delete', 'admin'];
PERMISSIONS['editor'] = ['read', 'write'];
PERMISSIONS['viewer'] = ['read'];

function hasPermission(role, action) {
  const perms = PERMISSIONS[role];
  if (!perms) return false;
  return perms.includes(action);
}

// Document store
const documents = Object.create(null);

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    let size = 0;
    req.on('data', chunk => {
      size += chunk.length;
      if (size > 65536) { reject(new Error('Body too large')); return; }
      body += chunk;
    });
    req.on('end', () => {
      try { resolve(JSON.parse(body)); }
      catch(e) { reject(new Error('Invalid JSON')); }
    });
  });
}

function sanitizeDocId(id) {
  if (typeof id !== 'string') return null;
  if (id.length > 64) return null;
  if (!/^[a-zA-Z0-9_-]+$/.test(id)) return null;
  return id;
}

// Role elevation endpoint - allows users to request temporary elevated access
function handleElevation(req, tokenPayload, body) {
  if (!body || typeof body !== 'object') return { status: 403, body: {error: 'Invalid request'} };

  const requestedRole = body.requestedRole;
  if (typeof requestedRole !== 'string') return { status: 400, body: {error: 'Missing role'} };

  // Security check: users can only elevate to roles below admin
  const allowedElevations = ['editor', 'viewer'];

  // Normalize the requested role for comparison
  const normalizedRole = requestedRole.trim().toLowerCase();

  if (!allowedElevations.includes(normalizedRole)) {
    return { status: 403, body: {error: 'Cannot elevate to that role'} };
  }

  // Generate new token with the validated normalized role
  const newToken = generateToken(tokenPayload.sub, normalizedRole, 300);
  return { status: 200, body: {token: newToken, expiresIn: 300} };
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const path = url.pathname;

  res.setHeader('Content-Type', 'application/json');

  // Login endpoint
  if (path === '/api/login' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const { username, password } = body;
      if (typeof username !== 'string' || typeof password !== 'string') {
        res.writeHead(400); res.end(JSON.stringify({error: 'Invalid credentials format'})); return;
      }
      if (username.length > 64 || password.length > 128) {
        res.writeHead(400); res.end(JSON.stringify({error: 'Input too long'})); return;
      }
      const user = users[username];
      if (!user) {
        // Constant-time fake computation with a random salt to prevent user enumeration
        crypto.scryptSync(password, crypto.randomBytes(16).toString('hex'), 64);
        res.writeHead(401); res.end(JSON.stringify({error: 'Invalid credentials'})); return;
      }
      const hash = crypto.scryptSync(password, user.salt, 64).toString('hex');
      if (!timingSafeCompare(hash, user.passwordHash)) {
        res.writeHead(401); res.end(JSON.stringify({error: 'Invalid credentials'})); return;
      }
      const token = generateToken(username, user.role, 3600);
      res.writeHead(200); res.end(JSON.stringify({token})); return;
    } catch(e) {
      res.writeHead(400); res.end(JSON.stringify({error: 'Bad request'})); return;
    }
  }

  // All other endpoints require auth
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.writeHead(401); res.end(JSON.stringify({error: 'Unauthorized'})); return;
  }
  const tokenPayload = verifyToken(authHeader.slice(7));
  if (!tokenPayload) {
    res.writeHead(401); res.end(JSON.stringify({error: 'Invalid token'})); return;
  }

  // Role elevation
  if (path === '/api/elevate' && req.method === 'POST') {
    try {
      const body = await parseBody(req);
      const result = handleElevation(req, tokenPayload, body);
      res.writeHead(result.status); res.end(JSON.stringify(result.body)); return;
    } catch(e) {
      res.writeHead(400); res.end(JSON.stringify({error: 'Bad request'})); return;
    }
  }

  // Document operations
  if (path === '/api/documents' && req.method === 'GET') {
    if (!hasPermission(tokenPayload.role, 'read')) {
      res.writeHead(403); res.end(JSON.stringify({error: 'Forbidden'})); return;
    }
    res.writeHead(200); res.end(JSON.stringify({documents: Object.keys(documents)})); return;
  }

  if (path.startsWith('/api/documents/') && req.method === 'GET') {
    if (!hasPermission(tokenPayload.role, 'read')) {
      res.writeHead(403); res.end(JSON.stringify({error: 'Forbidden'})); return;
    }
    const docId = sanitizeDocId(path.slice('/api/documents/'.length));
    if (!docId) { res.writeHead(400); res.end(JSON.stringify({error: 'Invalid doc ID'})); return; }
    if (!(docId in documents)) { res.writeHead(404); res.end(JSON.stringify({error: 'Not found'})); return; }
    res.writeHead(200); res.end(JSON.stringify({id: docId, content: documents[docId]})); return;
  }

  if (path === '/api/documents' && req.method === 'POST') {
    if (!hasPermission(tokenPayload.role, 'write')) {
      res.writeHead(403); res.end(JSON.stringify({error: 'Forbidden'})); return;
    }
    try {
      const body = await parseBody(req);
      const docId = sanitizeDocId(body.id);
      if (!docId) { res.writeHead(400); res.end(JSON.stringify({error: 'Invalid doc ID'})); return; }
      if (typeof body.content !== 'string' || body.content.length > 10000) {
        res.writeHead(400); res.end(JSON.stringify({error: 'Invalid content'})); return;
      }
      documents[docId] = body.content;
      res.writeHead(201); res.end(JSON.stringify({id: docId})); return;
    } catch(e) {
      res.writeHead(400); res.end(JSON.stringify({error: 'Bad request'})); return;
    }
  }

  if (path.startsWith('/api/documents/') && req.method === 'DELETE') {
    if (!hasPermission(tokenPayload.role, 'delete')) {
      res.writeHead(403); res.end(JSON.stringify({error: 'Forbidden'})); return;
    }
    const docId = sanitizeDocId(path.slice('/api/documents/'.length));
    if (!docId) { res.writeHead(400); res.end(JSON.stringify({error: 'Invalid doc ID'})); return; }
    delete documents[docId];
    res.writeHead(200); res.end(JSON.stringify({deleted: true})); return;
  }

  res.writeHead(404); res.end(JSON.stringify({error: 'Not found'}));
});

server.listen(3000);
